CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL UNIQUE COLLATE NOCASE, password_hash TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('Administrator','Staff')), permissions TEXT NOT NULL DEFAULT '{}', active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(token_hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id),csrf TEXT NOT NULL,expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS courses(id TEXT PRIMARY KEY,name TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS intakes(id TEXT PRIMARY KEY,name TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS schedules(id TEXT PRIMARY KEY,name TEXT NOT NULL,active INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS students(id TEXT PRIMARY KEY,student_number TEXT UNIQUE NOT NULL,full_name TEXT NOT NULL,preferred_name TEXT NOT NULL DEFAULT '',email TEXT NOT NULL COLLATE NOCASE,phone TEXT NOT NULL,country TEXT NOT NULL,promotional_consent INTEGER NOT NULL DEFAULT 0,unsubscribed INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS students_email ON students(email);
CREATE TABLE IF NOT EXISTS applications(id TEXT PRIMARY KEY,reference TEXT UNIQUE NOT NULL,full_name TEXT NOT NULL,preferred_name TEXT NOT NULL DEFAULT '',email TEXT NOT NULL COLLATE NOCASE,phone TEXT NOT NULL,country TEXT NOT NULL,course_id TEXT REFERENCES courses(id),intake_id TEXT REFERENCES intakes(id),schedule_id TEXT REFERENCES schedules(id),current_level TEXT NOT NULL,category TEXT NOT NULL DEFAULT 'class-only',message TEXT NOT NULL DEFAULT '',privacy_acknowledged INTEGER NOT NULL,promotional_consent INTEGER NOT NULL DEFAULT 0,unsubscribed INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'New',assigned_to TEXT REFERENCES users(id),student_id TEXT REFERENCES students(id),duplicate_of TEXT REFERENCES applications(id),archived_at TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS applications_filters ON applications(archived_at,status,course_id,intake_id,created_at);
CREATE INDEX IF NOT EXISTS applications_email ON applications(email);
CREATE INDEX IF NOT EXISTS applications_assignee ON applications(assigned_to);
CREATE TABLE IF NOT EXISTS submission_keys(key TEXT PRIMARY KEY,fingerprint TEXT NOT NULL,application_id TEXT NOT NULL REFERENCES applications(id),created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS submission_fingerprint ON submission_keys(fingerprint,created_at);
CREATE TABLE IF NOT EXISTS form_challenges(token TEXT PRIMARY KEY,created_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS rate_limits(key TEXT PRIMARY KEY,count INTEGER NOT NULL,reset_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS notes(id TEXT PRIMARY KEY,application_id TEXT REFERENCES applications(id),student_id TEXT REFERENCES students(id),actor_id TEXT REFERENCES users(id),body TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS tags(id TEXT PRIMARY KEY,name TEXT UNIQUE NOT NULL);
CREATE TABLE IF NOT EXISTS application_tags(application_id TEXT REFERENCES applications(id),tag_id TEXT REFERENCES tags(id),PRIMARY KEY(application_id,tag_id));
CREATE TABLE IF NOT EXISTS status_history(id TEXT PRIMARY KEY,application_id TEXT NOT NULL REFERENCES applications(id),from_status TEXT,to_status TEXT NOT NULL,actor_id TEXT REFERENCES users(id),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS templates(id TEXT PRIMARY KEY,name TEXT NOT NULL,subject TEXT NOT NULL,html TEXT NOT NULL,text TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('operational','promotional')),archived_at TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS campaigns(id TEXT PRIMARY KEY,subject TEXT NOT NULL,html TEXT NOT NULL,text TEXT NOT NULL,template_id TEXT REFERENCES templates(id),kind TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'Draft',actor_id TEXT REFERENCES users(id),confirmation_token TEXT NOT NULL,selection TEXT NOT NULL DEFAULT '{}',confirmed_at TEXT,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS email_recipients(id TEXT PRIMARY KEY,campaign_id TEXT NOT NULL REFERENCES campaigns(id),application_id TEXT REFERENCES applications(id),student_id TEXT REFERENCES students(id),email TEXT NOT NULL,full_name TEXT NOT NULL,subject TEXT NOT NULL,html TEXT NOT NULL,text TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'Draft',attempt_count INTEGER NOT NULL DEFAULT 0,next_attempt_at TEXT,accepted_at TEXT,error TEXT,unsubscribe_token TEXT UNIQUE,UNIQUE(campaign_id,email));
CREATE INDEX IF NOT EXISTS email_queue ON email_recipients(status,next_attempt_at);
CREATE TABLE IF NOT EXISTS email_attempts(id TEXT PRIMARY KEY,recipient_id TEXT NOT NULL REFERENCES email_recipients(id),started_at TEXT NOT NULL,finished_at TEXT,status TEXT NOT NULL,error TEXT);
CREATE TABLE IF NOT EXISTS audit_events(id INTEGER PRIMARY KEY AUTOINCREMENT,actor_id TEXT REFERENCES users(id),actor_name TEXT NOT NULL,action TEXT NOT NULL,record_type TEXT NOT NULL,record_id TEXT,details TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS audit_time ON audit_events(created_at);
CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS migrations(version TEXT PRIMARY KEY,applied_at TEXT NOT NULL);
